typedef float rational_t;

class vector3d
{
public:
  float x, y, z;
};

inline rational_t dot(const vector3d& a, const vector3d& b)
{
  return a.x*b.x + a.y*b.y + a.z*b.z;
}

class sphere
{
public:
  const vector3d& get_center() const { return center; }
  rational_t get_radius() const { return radius; }
  inline bool intersects(const sphere& v) const
  {
    vector3d d = { center.x-v.center.x, center.y-v.center.y, center.z-v.center.z };
    rational_t r = radius+v.radius;
    return d.x*d.x+d.y*d.y+d.z*d.z <= r*r;
  }
private:
  vector3d center;
  rational_t radius;
};

class plane
{
public:
  plane(const vector3d& point_on_surface, const vector3d& normal);
  rational_t distance_above(const vector3d& pt) const
  {
    return dot(unit_normal, pt) - odistance;
  }
  rational_t odistance;
  vector3d unit_normal;
};

extern "C" float fabsf(float);
#define __fabs(f) fabsf(f)

class portal
{
public:
  bool touches_sphere(const sphere& s) const;
private:
